module OLED_Top(
	sys_clk,
	rst_n,
	dht11_done,
	tempH,
	tempL,
	humidityL,
	light_data,
	humidityH,
	OLED_SCL,
	init_req,
	refresh_req,
	showfont_req,
	show_THdata_req,
	show_Lightdata_req,
	IICSlave,
	IICdata,
	OLED_SDA);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input dht11_done;
	input [7:0] tempH;
	input [7:0] tempL;
	input [7:0] humidityL;
	input [15:0] light_data;
	input [7:0] humidityH;
	output OLED_SCL;
	output init_req;
	output refresh_req;
	output showfont_req;
	output show_THdata_req;
	output show_Lightdata_req;
	output [15:0] IICSlave;
	output [7:0] IICdata;
	inout OLED_SDA;

	wire sys_clk;
	wire rst_n;
	wire dht11_done;
	wire [7:0] tempH;
	wire [7:0] tempL;
	wire [7:0] humidityL;
	wire [15:0] light_data;
	wire [7:0] humidityH;
	wire OLED_SCL;
	wire init_req;
	wire refresh_req;
	wire showfont_req;
	wire show_THdata_req;
	wire show_Lightdata_req;
	wire [15:0] IICSlave;
	wire [7:0] IICdata;
	wire OLED_SDA;
	wire IIC_Driver2_IICWriteDone;
	wire [7:0] OLED_FontData8_data;
	wire OLED_ShowFont7_font_row;
	wire [5:0] OLED_ShowFont7_font_index;
	wire [8:0] OLED_ShowFont7_ShowFont_index_after;
	wire [7:0] OLED_NumData_Light_data;
	wire [3:0] OLED_ShowData_Light6_font_index_after;
	wire [4:0] OLED_ShowData_Light6_font;
	wire OLED_ShowData_Light6_font_row;
	wire [23:0] OLED_Init1_Init_data;
	wire [23:0] OLED_Refresh4_refresh_data;
	wire [23:0] OLED_ShowFont7_ShowFont_Data;
	wire [23:0] OLED_ShowData_Light6_show_Lightdata;
	wire OLED_SelData8_IICWriteReq;
	wire [7:0] TH_NumData10_data;
	wire [3:0] OLED_ShowData_TH9_font_index_after;
	wire [4:0] OLED_ShowData_TH9_font;
	wire OLED_ShowData_TH9_font_row;
	wire [23:0] OLED_ShowData_TH9_show_THdata;

	//----Code starts here: integrated by Robei-----
	localparam	OLED_INIT 		= 5 'd0;			                //初始化
	localparam	OLED_Refresh	=  5'd1;			            //清零
	localparam  OLED_ShowFont	=	5'd2;			            //显示字符
	localparam	OLED_IDLE 		=  5'd4;			            //空闲
	localparam	OLED_ShowData_TH	=	5'd8;			    //显示温湿度数据
	localparam	OLED_ShowData_Light	=	5'd16;			//显示光照数据
	wire init_finish;
	wire refresh_finish;
	wire showfont_finish;
	wire show_THdata_finish;
	wire show_Lightdata_finish;
	wire[23:0]IICWriteData;
	reg[4:0]	state , next_state;
	
	assign init_req     = (state == OLED_INIT)     ? 1'b1 : 1'b0;
	
	assign refresh_req  = (state == OLED_Refresh)  ? 1'b1 : 1'b0;
	
	assign showfont_req = (state == OLED_ShowFont) ? 1'b1 : 1'b0;
	
	assign show_THdata_req = (state == OLED_ShowData_TH) ? 1'b1 : 1'b0;
	
	assign show_Lightdata_req =(state == OLED_ShowData_Light)? 1'b1 : 1'b0;
	
	                     
	assign IICSlave[15:0] ={IICWriteData[15:8],IICWriteData[23:16]};
	assign IICdata[7:0]=IICWriteData[7:0];
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			state <= OLED_INIT;
		else
			state <= next_state;
	end
	
	always@(*)
	begin
		case(state)
		
	OLED_INIT:
			if(init_finish == 1'b1)
				next_state <= OLED_Refresh;
			else
				next_state <= OLED_INIT;
		
	OLED_Refresh:
			if(refresh_finish == 1'b1)
			   next_state <= OLED_ShowFont;
			else
				next_state <= OLED_Refresh;
		
	OLED_ShowFont:
			if(showfont_finish == 1'b1)
			   next_state <= OLED_IDLE;
			else
				next_state <= OLED_ShowFont;
		
	OLED_IDLE:
		    if(dht11_done == 1'b1)
				next_state <= OLED_ShowData_TH;
		    else
				next_state <= OLED_IDLE;
		
	OLED_ShowData_TH:
			if(show_THdata_finish == 1'b1)
			    next_state <= OLED_ShowData_Light;
			else
				next_state <= OLED_ShowData_TH;
		
	OLED_ShowData_Light:
		       if(show_Lightdata_finish == 1'b1)
		         next_state <= OLED_IDLE;
		       else
		       next_state <= OLED_ShowData_Light;
		default: next_state <= OLED_INIT;
		endcase
	end
	
	
	
	//---Module instantiation---
	OLED_Init OLED_Init1(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.init_req(init_req),
		.write_done(IIC_Driver2_IICWriteDone),
		.init_finish(init_finish),
		.Init_data(OLED_Init1_Init_data));

	IIC_Driver IIC_Driver2(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.IICSlave(IICSlave),
		.IICWriteReq(OLED_SelData8_IICWriteReq),
		.IICWriteData(IICdata),
		.IICSCL(OLED_SCL),
		.IICWriteDone(IIC_Driver2_IICWriteDone),
		.IICSDA(OLED_SDA));

	OLED_Refresh OLED_Refresh4(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.refresh_req(refresh_req),
		.write_done(IIC_Driver2_IICWriteDone),
		.refresh_finish(refresh_finish),
		.refresh_data(OLED_Refresh4_refresh_data));

	OLED_ShowFont OLED_ShowFont7(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.ShowFont_req(showfont_req),
		.write_done(IIC_Driver2_IICWriteDone),
		.fontdata(OLED_FontData8_data),
		.ShowFont_Data(OLED_ShowFont7_ShowFont_Data),
		.font_row(OLED_ShowFont7_font_row),
		.ShowFont_finish(ShowFont_finish),
		.font_index(OLED_ShowFont7_font_index),
		.ShowFont_index_after(OLED_ShowFont7_ShowFont_index_after));

	OLED_FontData OLED_FontData8(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.font_row(OLED_ShowFont7_font_row),
		.font_sel(OLED_ShowFont7_font_index),
		.index(OLED_ShowFont7_ShowFont_index_after),
		.data(OLED_FontData8_data));

	OLED_ShowData_Light OLED_ShowData_Light6(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.light_data(light_data),
		.fontdata(OLED_NumData_Light_data),
		.show_Lightdata_req(show_Lightdata_req),
		.write_done(IIC_Driver2_IICWriteDone),
		.show_Lightdata(OLED_ShowData_Light6_show_Lightdata),
		.font_row(OLED_ShowData_Light6_font_row),
		.show_Lightdata_finish(show_Lightdata_finish),
		.font(OLED_ShowData_Light6_font),
		.font_index_after(OLED_ShowData_Light6_font_index_after));

	OLED_NumData OLED_NumData_Light(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.font_row(OLED_ShowData_Light6_font_row),
		.font_sel(OLED_ShowData_Light6_font),
		.index(OLED_ShowData_Light6_font_index_after),
		.data(OLED_NumData_Light_data));

	OLED_SelData OLED_SelData8(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.init_req(init_req),
		.init_data(OLED_Init1_Init_data),
		.refresh_req(refresh_req),
		.refresh_data(OLED_Refresh4_refresh_data),
		.showfont_req(showfont_req),
		.showfont_data(OLED_ShowFont7_ShowFont_Data),
		.show_THdata_req(show_THdata_req),
		.show_THdata(OLED_ShowData_TH9_show_THdata),
		.show_Lightdata(OLED_ShowData_Light6_show_Lightdata),
		.show_Lightdata_req(show_Lightdata_req),
		.IICWriteReq(OLED_SelData8_IICWriteReq),
		.IICWriteData(IICWriteData));

	OLED_ShowData_TH OLED_ShowData_TH9(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.data_done(dht11_done),
		.tempH(tempH),
		.tempL(tempL),
		.humidityH(humidityH),
		.humidityL(humidityL),
		.fontdata(TH_NumData10_data),
		.show_THdata_req(show_THdata_req),
		.write_done(IIC_Driver2_IICWriteDone),
		.show_THdata(OLED_ShowData_TH9_show_THdata),
		.show_THdata_finish(show_THdata_finish),
		.font_row(OLED_ShowData_TH9_font_row),
		.font(OLED_ShowData_TH9_font),
		.font_index_after(OLED_ShowData_TH9_font_index_after));

	OLED_NumData TH_NumData10(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.font_row(OLED_ShowData_TH9_font_row),
		.font_sel(OLED_ShowData_TH9_font),
		.index(OLED_ShowData_TH9_font_index_after),
		.data(TH_NumData10_data));

endmodule    //OLED_Top

